insert into public.restaurant_verifications
  (restaurant_id, verification_type_id, rating, awarded_year, is_verified, metadata)
select r.id, vt.id, v.rating, v.year, true, v.metadata
from (values
  ('centennial', 'centennial-춘천-봄담은산채', 'centennial', null, 2025, '{"desc":"자체개발 메뉴인 산채오리전골이 주 메뉴로 산지직송과 농가직거래 등으로 재료를 수급하여 품질을 유지"}'::jsonb),
  ('centennial', 'centennial-춘천-예미옥주식회사', 'centennial', null, 2025, '{"desc":"6.25 한국전쟁 당시 대구로 피난 간 1대 대표가 지금의 신천시장 인근에서 팔던 선지해장국을 시작으로 현재는 3대째 운영"}'::jsonb),
  ('centennial', 'centennial-춘천-대원당', 'centennial', null, 2025, '{"desc":"개업 후 2대에 걸쳐 춘천지역을 대표하는 빵집으로 성장한 대원당은 버터 100% 사용의 좋은 재료로 약 500여종의 빵을 제조"}'::jsonb),
  ('centennial', 'centennial-춘천-라모스', 'centennial', null, 2025, '{"desc":"춘천에 주둔했던 미군 부대 캠프페이지의 총괄 주방 책임자였던 외할아버지께서 오픈한 햄버거 가게를 기반으로 3대째 대를 이어옴"}'::jsonb),
  ('centennial', 'centennial-춘천-이디오피아집(벳)', 'centennial', null, 2025, '{"desc":"1950년 한국전쟁 당시 UN 참전국 일원으로 이디오피아군이 참여한 것을 기념하기 위하여 황제가 이디오피아 기념관 건립"}'::jsonb),
  ('centennial', 'centennial-춘천-춘천명물닭갈비', 'centennial', null, 2025, '{"desc":"닭갈비는 수많은 시행착오를 거쳐 탄생한 양념장으로 숙성시켜 자극적이지 않고 담백하며 볶을 때는 기름을 별도로 사용하지 않음"}'::jsonb),
  ('centennial', 'centennial-춘천-실비막국수', 'centennial', null, 2025, '{"desc":"창업주로부터 이어받아 부부가 공동 운영 중인 곳으로 현재 3대 아들부부가 6년 전부터 비법을 전수 받고 있으며 합리적인 가격 유지"}'::jsonb),
  ('centennial', 'centennial-춘천-주식회사명가막국수', 'centennial', null, 2025, '{"desc":"제2회 막국수 닭갈비 축제에서 명가로 선정된 업체로 모친에게도 공유하지 않는 양념장과 열무김치로 점포의 인기를 끌고 있음"}'::jsonb),
  ('centennial', 'centennial-춘천-원조남부막국수', 'centennial', null, 2025, '{"desc":"대통령이 방문하신 집이라는 자부심과 함께 매일 아침 대표가 직접 식재료와 맛을 확인해가며 변함없는 맛을 강조"}'::jsonb),
  ('centennial', 'centennial-춘천-샘밭막국수', 'centennial', null, 2025, '{"desc":"1970년 개업 후 3대째 이어지며 현재 약 50년의 업력을 자랑하고 있는 막국수 전문점으로 모친 때부터 이어온 전통의 맛 유지"}'::jsonb),
